// In .csproj:
// <Nullable>enable</Nullable>

#nullable enable
string BuildKey(string tenantId, string userId)
    => $"session:{tenantId}:{userId}";

#nullable disable
// Legacy generated code island — no NRT warnings here
#nullable restore

string? ReadSessionJson(IDatabase redis, string key)
{
    RedisValue value = redis.StringGet(key);
    return value.HasValue ? value.ToString() : null;
}

int SessionLength(string? json)
    => json is not null ? json.Length : 0;

// Smell: silencing the compiler without proof
public sealed class BadOptions
{
    public string Connection = null!;
}

// Better: constructor or required property
public sealed class GoodOptions
{
    public required string Connection { get; init; }
}
